---
import { cn } from '@/utils/cn';
import type { HTMLAttributes } from 'astro/types';

export interface Props extends HTMLAttributes<'nav'> {}

const { class: className, ...props } = Astro.props;
---

<nav aria-label="breadcrumb" class={className} {...props}>
  <slot />
</nav>

---
import { cn } from '@/utils/cn';
import type { HTMLAttributes } from 'astro/types';
import HugeIcon from "../icon/HugeIcon.astro";
import { MoreHorizontalIcon } from "../icon/icons";

export interface Props extends HTMLAttributes<'span'> {}

const { class: className, ...props } = Astro.props;
---

<span
  role="presentation"
  aria-hidden="true"
  class={cn('flex size-9 items-center justify-center', className)}
  {...props}
>
  <HugeIcon icon={MoreHorizontalIcon} class="size-4" />
  <span class="sr-only">More</span>
</span>

